import{_ as l,a0 as a,w as p,s as u,I as t,x as e,a1 as i,A as r,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"如何在 Docker 容器中運行 Kali Linux 2.0 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Docker 容器中運行 Kali Linux 2.0 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Docker 容器中運行 Kali Linux 2.0 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Docker 容器中運行 Kali Linux 2.0 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150826 How to Run Kali Linux 2.0 In Docker Container","title":"如何在 Docker 容器中運行 Kali Linux 2.0","tag":"201508","desc":""},"relativePath":"201508/20150826 How to Run Kali Linux 2.0 In Docker Container.md","filePath":"[post].md"}'),s={name:"201508/20150826 How to Run Kali Linux 2.0 In Docker Container.md"};function k(c,o,x,m,L,b){const n=a("Link");return p(),u("div",null,[o[16]||(o[16]=t("h1",{id:"如何在-docker-容器中運行-kali-linux-2-0",tabindex:"-1"},[e("如何在 Docker 容器中運行 Kali Linux 2.0 "),t("a",{class:"header-anchor",href:"#如何在-docker-容器中運行-kali-linux-2-0","aria-label":"Permalink to “如何在 Docker 容器中運行 Kali Linux 2.0”"},"​")],-1)),o[17]||(o[17]=t("h3",{id:"介紹",tabindex:"-1"},[e("介紹 "),t("a",{class:"header-anchor",href:"#介紹","aria-label":"Permalink to “介紹”"},"​")],-1)),t("p",null,[o[1]||(o[1]=e("Kali Linux 是一個對於安全測試人員和白帽的一個知名操作系統。它帶有大量安全相關的程序，這讓它很容易用於滲透測試。最近，",-1)),i(n,{href:"https://linux.cn/article-6005-1.html"},{default:r(()=>[...o[0]||(o[0]=[e("Kali Linux 2.0",-1)])]),_:1}),o[2]||(o[2]=e(" 發佈了，它被認為是這個操作系統最重要的一次發佈。另一方面，Docker 技術由於它的可擴展性和易用性讓它變得很流行。Dokcer 讓你非常容易地將你的程序帶給你的用户。好消息是你可以通過 Docker 運行Kali Linux 了，讓我們看看該怎麼做 😃",-1))]),o[18]||(o[18]=d(`<h3 id="在-docker-中運行-kali-linux-2-0" tabindex="-1">在 Docker 中運行 Kali Linux 2.0 <a class="header-anchor" href="#在-docker-中運行-kali-linux-2-0" aria-label="Permalink to “在 Docker 中運行 Kali Linux 2.0”">​</a></h3><p><strong>相關提示</strong></p><blockquote><p>如果你還沒有在系統中安裝docker，你可以運行下面的命令：</p></blockquote><blockquote><p><strong>對於 Ubuntu/Linux Mint/Debian：</strong></p></blockquote><blockquote><pre><code>sudo apt-get install docker 
</code></pre></blockquote><blockquote><p><strong>對於 Fedora/RHEL/CentOS：</strong></p></blockquote><blockquote><pre><code>sudo yum install docker 
</code></pre></blockquote><blockquote><p><strong>對於 Fedora 22：</strong></p></blockquote><blockquote><pre><code>dnf install docker 
</code></pre></blockquote><blockquote><p>你可以運行下面的命令來啓動docker：</p></blockquote><blockquote><pre><code>sudo docker start 
</code></pre></blockquote><p>首先運行下面的命令確保 Docker 服務運行正常：</p><pre><code>sudo docker status 
</code></pre><p>Kali Linux 的開發團隊已將 Kali Linux 的 docker 鏡像上傳了，只需要輸入下面的命令來下載鏡像。</p><pre><code>docker pull kalilinux/kali-linux-docker 
</code></pre><p><img src="http://linuxpitstop.com/wp-content/uploads/2015/08/129.png" alt="Pull Kali Linux docker"></p><p>下載完成後，運行下面的命令來找出你下載的 docker 鏡像的 ID。</p><pre><code>docker images 
</code></pre><p><img src="http://linuxpitstop.com/wp-content/uploads/2015/08/230.png" alt="Kali Linux Image ID"></p><p>現在運行下面的命令來從鏡像文件啓動 kali linux docker 容器（這裏需用正確的鏡像ID替換）。</p><pre><code>docker run -i -t 198cd6df71ab3 /bin/bash 
</code></pre><p>它會立刻啓動容器並且讓你登錄到該操作系統，你現在可以在 Kaili Linux 中工作了。</p><p><img src="http://linuxpitstop.com/wp-content/uploads/2015/08/328.png" alt="Kali Linux Login"></p><p>你可以在容器外面通過下面的命令來驗證容器已經啓動/運行中了：</p><pre><code>docker ps 
</code></pre><p><img src="http://linuxpitstop.com/wp-content/uploads/2015/08/421.png" alt="Docker Kali"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>Docker 是一種最聰明的用來部署和分發包的方式。Kali Linux docker 鏡像非常容易上手，也不會消耗很大的硬盤空間，這樣也可以很容易地在任何安裝了 docker 的操作系統上測試這個很棒的發行版了。</p><hr>`,29)),t("p",null,[o[4]||(o[4]=e("via: ",-1)),i(n,{href:"http://linuxpitstop.com/run-kali-linux-2-0-in-docker-container/"},{default:r(()=>[...o[3]||(o[3]=[e("http://linuxpitstop.com/run-kali-linux-2-0-in-docker-container/",-1)])]),_:1})]),t("p",null,[o[8]||(o[8]=e("作者：",-1)),i(n,{href:"http://linuxpitstop.com/author/aun/"},{default:r(()=>[...o[5]||(o[5]=[e("Aun",-1)])]),_:1}),o[9]||(o[9]=e(" 譯者：",-1)),i(n,{href:"https://github.com/geekpi"},{default:r(()=>[...o[6]||(o[6]=[e("geekpi",-1)])]),_:1}),o[10]||(o[10]=e(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:r(()=>[...o[7]||(o[7]=[e("wxy",-1)])]),_:1})]),t("p",null,[o[13]||(o[13]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[11]||(o[11]=[e("LCTT",-1)])]),_:1}),o[14]||(o[14]=e(" 原創翻譯，",-1)),i(n,{href:"https://linux.cn/"},{default:r(()=>[...o[12]||(o[12]=[e("Linux中國",-1)])]),_:1}),o[15]||(o[15]=e(" 榮譽推出",-1))])])}const K=l(s,[["render",k]]);export{D as __pageData,K as default};
